INSERT INTO t_p88532089_it_company_website_r.legal_documents (case_id, doc_type, title, content)
SELECT 2, 'objection', 'Возражения и ходатайство по ст. 333 ГК РФ', 'ВОЗРАЖЕНИЯ НА ИСКОВОЕ ЗАЯВЛЕНИЕ и ходатайство о снижении неустойки и процентов (ст. 333 ГК РФ)
В Самарский районный суд г. Самары. Истец: ООО «Декоратор». Ответчик 1: ООО «СК Авангард». Ответчик 2: Тюрин А.В.

1. ОСНОВНОЙ ДОЛГ ПОГАШЕН. Задолженность 86 267,82 руб. погашена добровольно, платёжное поручение прилагается. В этой части в иске отказать. Погашение без принуждения подтверждает добросовестность ответчиков.

2. НЕСОРАЗМЕРНОСТЬ САНКЦИЙ. При долге 86 267,82 руб. истец требует 112 151,13 руб. процентов и 22 430,23 руб. неустойки — всего 134 581,36 руб., это в 1,56 раза больше долга. Ставка 0,5%/день = 182,5% годовых; неустойка 0,1%/день = 36,5% годовых; совокупно ~219% годовых. Многократно превышает ключевую ставку ЦБ. Обязательства исполнены более чем на 95% (оплачено 1 624 425,90 из 1 710 693,72). Убытки истцом не доказаны.

3. ПРОЦЕНТЫ ПО п.4.4 — СКРЫТАЯ НЕУСТОЙКА. Довод истца о неприменимости ст. 333 ГК РФ несостоятелен. Плата 182,5% годовых не отвечает признакам обычной платы за пользование деньгами и по существу направлена на понуждение к исполнению, то есть является мерой ответственности. Значение имеет существо отношения, а не название в договоре. Одновременное начисление процентов и неустойки за одно нарушение — двойная ответственность. Взыскание санкций сверх суммы долга при исполнении на 95% — злоупотребление правом (п. 2 ст. 10 ГК РФ).

4. ИСТЕЦ СОДЕЙСТВОВАЛ РОСТУ ДОЛГА (ст. 404 ГК РФ). Просрочка с 25.09.2023, претензия направлена только 26.06.2026 — через 2 года 9 месяцев. Отгрузки продолжались до 13.05.2026 без приостановления и требований оплаты. Бездействие истца многократно увеличило начисления.

5. ДЕФЕКТЫ ТРЕБОВАНИЙ. Пункты 3 и 4 просительной части заявлены о взыскании «с Тюрина А.В. солидарно» без указания второго должника — солидарность с одним лицом невозможна (ст. 322 ГК РФ). Проценты на будущее заявлены «от стоимости поставленного товара», а не от остатка долга — ведёт к неосновательному обогащению, требуется проверка Приложения № 2.

ПРОШУ СУД:
1. Отказать во взыскании 86 267,82 руб. в связи с добровольным погашением до вынесения решения.
2. Применить ст. 333 ГК РФ и снизить неустойку до размера по ключевой ставке ЦБ.
3. Снизить проценты 112 151,13 руб. как явно несоразмерные и являющиеся скрытой мерой ответственности.
4. Отказать во взыскании процентов и неустойки на будущее время в связи с погашением долга.
5. Обязать истца представить расчёт с базой начисления по каждой партии с учётом платежей.
6. Распределить госпошлину пропорционально удовлетворённым требованиям.

ПРИЛОЖЕНИЯ: платёжное поручение о погашении долга; контррасчёт процентов и неустойки; сведения о ключевой ставке ЦБ; копия возражений для истца с документом о направлении; документ о полномочиях представителя.'
WHERE NOT EXISTS (SELECT 1 FROM t_p88532089_it_company_website_r.legal_documents WHERE case_id=2 AND doc_type='objection');